41 |   async loginWithSso(assertion: SsoAssertion, requestId?: string): Promise<Session> {
42 |     if (!assertion.issuer.startsWith('https://')) throw new UnauthorizedError('Untrusted SSO issuer');
43 |     const user = await this.db.findOne<UserRecord>('users', { ssoSubject: `${issuerSlug(assertion.issuer)}|${assertion.subject}` });
44 |     if (!user) {
45 |       log.warn('auth.login_failed', { requestId, method: 'sso', issuer: assertion.issuer });
46 |       throw new UnauthorizedError('No account linked to this SSO identity');
47 |     }
48 |     const session = this.sessions.create({ userId: user.id, customerId: user.customerId, method: 'sso' });
49 |     log.info('auth.login_succeeded', { requestId, method: 'sso', userId: user.id, sessionId: session.id });
50 |     return session;
