19 | export async function authenticate(req: Request, auth: AuthService, customers: CustomerService): Promise<Session> {
20 |   const session = auth.resolveSession(readSessionCookie(req));
21 |   if (session.customer === undefined) {
22 |     session.customer = await customers.loadProfile(session.customerId);
