8 | 
9 |   create(input: { userId: string; customerId: string; method: LoginMethod }): Session {
10 |     const session: Session = {
11 |       id: `sess_${randomUUID().slice(0, 12)}`,
12 |       userId: input.userId,
13 |       customerId: input.customerId,
14 |       method: input.method,
15 |       createdAt: Date.now(),
